# apü client runtime for Python (standard library only; Python ≥ 3.11). Embedded into every module
# generated by `apue-types --lang python`; the generated part below adds the API's types and methods.
# HTTP/1.1 over TLS with keep-alive (http.client). One connection per client: not thread-safe.
# Covers: unary calls (GET ?i= for cacheable reads, POST otherwise, Idempotency-Key for non-safe
# calls), server streams, client streams (half duplex: inputs are sent, then the response is read),
# RFC 9457 problems, deadlines, retries, bytes in messages (BLOB frames), uploads for bytes/file
# inputs (one request each, not resumed), t.download() outputs (resumed with Range + If-Range).
# Not covered: resume tokens for broken streams, batches, bidi full duplex, compression.
from __future__ import annotations

import hashlib
import http.client
import json
import math
import random
import ssl
import struct
import time
import urllib.parse
import uuid
from typing import Any, BinaryIO, Iterable, Iterator, Optional, Union

STREAM_JSON = "application/apue+json"
ACCEPT = "application/apue+json, application/json;q=0.9, application/problem+json;q=0.8"
MAX_GET_URL = 2048
MSG, END, BLOB, HEARTBEAT, CHECKPOINT = 0x00, 0x01, 0x02, 0x03, 0x04
FLAG_LAST = 0x02
BLOB_CHUNK = 64 * 1024


class ApueError(Exception):
    """An RFC 9457 problem: the call failed with `status` (HTTP semantics)."""

    def __init__(self, status: int, problem: Optional[dict] = None):
        self.status = status
        self.problem = problem or {}
        self.type = self.problem.get("type", "about:blank")
        self.title = self.problem.get("title", "Error")
        self.detail = self.problem.get("detail")
        self.retryable = bool(self.problem.get("retryable", False))
        super().__init__(f"{status} {self.title}" + (f": {self.detail}" if self.detail else ""))


def canonical_json(value: Any) -> str:
    """JSON with sorted keys and ES number formatting — close to RFC 8785 for cache-friendly GET URLs."""

    def number(n: float) -> str:
        if isinstance(n, bool):
            return "true" if n else "false"
        if isinstance(n, int):
            return str(n)
        if not math.isfinite(n):
            raise ValueError("NaN and infinities are not JSON")
        if n.is_integer() and abs(n) < 1e21:
            return str(int(n))
        return repr(n)

    def encode(v: Any) -> str:
        if v is None or isinstance(v, bool):
            return json.dumps(v)
        if isinstance(v, (int, float)):
            return number(v)
        if isinstance(v, str):
            return json.dumps(v, ensure_ascii=False)
        if isinstance(v, (list, tuple)):
            return "[" + ",".join(encode(x) for x in v) + "]"
        if isinstance(v, dict):
            keys = sorted(v.keys(), key=lambda k: k.encode("utf-16-be"))
            return "{" + ",".join(json.dumps(k, ensure_ascii=False) + ":" + encode(v[k]) for k in keys if v[k] is not _ABSENT) + "}"
        raise TypeError(f"not JSON-serialisable: {type(v).__name__}")

    return encode(value)


_ABSENT = object()


def _frame(kind: int, payload: bytes = b"", lane: int = 0, flags: int = 0) -> bytes:
    return struct.pack(">BBHI", kind, flags, lane, len(payload)) + payload


def _split_message(value: Any) -> tuple[Any, list[bytes]]:
    """bytes → {"$blob": k} (sent as BLOB frames first); look-alikes escaped as {"$lit": …}."""
    blobs: list[bytes] = []

    def extract(v: Any) -> Any:
        if isinstance(v, (bytes, bytearray, memoryview)):
            blobs.append(bytes(v))
            return {"$blob": len(blobs) - 1}
        if isinstance(v, list):
            return [extract(x) for x in v]
        if isinstance(v, dict):
            if len(v) == 1 and next(iter(v)) in ("$blob", "$lit"):
                return {"$lit": v}
            return {k: extract(x) for k, x in v.items()}
        return v

    return extract(value), blobs


def _restore(value: Any, blobs: list[bytes], used: set) -> Any:
    if isinstance(value, list):
        return [_restore(x, blobs, used) for x in value]
    if not isinstance(value, dict):
        return value
    if len(value) == 1 and "$lit" in value:
        return value["$lit"]
    if len(value) == 1 and "$blob" in value:
        index = value["$blob"]
        if not isinstance(index, int) or isinstance(index, bool) or not 0 <= index < len(blobs) or index in used:
            raise ApueError(502, {"title": "Malformed Stream", "detail": f"invalid blob reference {index!r}"})
        used.add(index)
        return blobs[index]
    return {k: _restore(x, blobs, used) for k, x in value.items()}


def _message_frames(value: Any) -> Iterator[bytes]:
    json_part, blobs = _split_message(value)
    for blob in blobs:
        if not blob:
            yield _frame(BLOB, b"", 0, FLAG_LAST)
        for offset in range(0, len(blob), BLOB_CHUNK):
            end = min(offset + BLOB_CHUNK, len(blob))
            yield _frame(BLOB, blob[offset:end], 0, FLAG_LAST if end == len(blob) else 0)
    yield _frame(MSG, json.dumps(json_part, separators=(",", ":")).encode())


def _transfers(schema: Any, kind: str) -> bool:
    """Whether a JSON Schema has `x-apue-transfer: kind` (or any of the given kinds) anywhere."""
    if isinstance(schema, dict):
        if schema.get("x-apue-transfer") in kind.split("|"):
            return True
        return any(_transfers(v, kind) for v in schema.values())
    if isinstance(schema, list):
        return any(_transfers(v, kind) for v in schema)
    return False


def _map(schema: dict, value: Any, kinds: tuple, fn) -> Any:
    """Applies fn at every position whose schema has x-apue-transfer in kinds (schema-directed)."""
    if value is None:
        return value
    if schema.get("x-apue-transfer") in kinds:
        return fn(value, schema["x-apue-transfer"])
    if "anyOf" in schema:
        branch = next((b for b in schema["anyOf"] if b.get("type") != "null"), None)
        return _map(branch, value, kinds, fn) if branch else value
    if schema.get("type") == "array" and isinstance(value, list):
        return [_map(schema.get("items", {}), x, kinds, fn) for x in value]
    if schema.get("type") == "object" and isinstance(value, dict):
        props = schema.get("properties", {})
        return {k: (_map(props[k], x, kinds, fn) if k in props else x) for k, x in value.items()}
    return value


class Download:
    """A t.download() output: `url` works as a plain link until `expires`; read() resumes and verifies."""

    def __init__(self, ref: dict, client: "ApueClientBase"):
        self.path: str = ref["$download"]
        self.url: str = client.base_url + self.path
        self.size: int = ref["size"]
        self.type: str = ref["type"]
        self.sha256: Optional[str] = ref.get("sha256")
        self.expires: str = ref["expires"]
        self._client = client

    def __repr__(self) -> str:
        return f"Download({self.url!r}, size={self.size}, type={self.type!r})"

    def stream(self) -> Iterator[bytes]:
        received, etag, failures = 0, None, 0
        digest = hashlib.sha256()
        while received < self.size or self.size == 0:
            headers = {} if received == 0 else {"range": f"bytes={received}-", **({"if-range": etag} if etag else {})}
            try:
                res = self._client._request("GET", self.path, headers, None)
                if res.status >= 400:
                    raise _problem(res.status, res.read())
                skip = 0
                if received == 0:
                    etag = res.getheader("etag")
                elif res.status == 206:
                    if not (res.getheader("content-range") or "").startswith(f"bytes {received}-"):
                        raise ApueError(502, {"title": "Bad Gateway", "detail": "download resumed at the wrong offset"})
                elif res.status == 200 and etag and res.getheader("etag") == etag:
                    skip = received
                else:
                    raise ApueError(502, {"title": "Bad Gateway", "detail": "the download changed while resuming"})
                while True:
                    chunk = res.read(BLOB_CHUNK)
                    if not chunk:
                        break
                    if skip:
                        cut = min(skip, len(chunk))
                        chunk, skip = chunk[cut:], skip - cut
                        if not chunk:
                            continue
                    if received + len(chunk) > self.size:
                        raise ApueError(502, {"title": "Bad Gateway", "detail": "download larger than announced"})
                    received += len(chunk)
                    digest.update(chunk)
                    yield chunk
                if self.size == 0 or received == self.size:
                    break
                raise ConnectionError(f"download ended after {received} of {self.size} bytes")
            except (OSError, http.client.HTTPException) as error:
                failures += 1
                self._client._drop()
                if failures > self._client.retries:
                    raise error
                time.sleep(random.random() * self._client.backoff * 2**failures)
        if self.sha256 is not None and digest.hexdigest() != self.sha256:
            raise ApueError(502, {"title": "Bad Gateway", "detail": "download content does not match its SHA-256"})

    def read(self) -> bytes:
        return b"".join(self.stream())


def _problem(status: int, body: bytes) -> ApueError:
    try:
        problem = json.loads(body) if body else None
    except ValueError:
        problem = None
    return ApueError(status, problem if isinstance(problem, dict) else {"title": http.client.responses.get(status, "Error")})


Uploadable = Union[bytes, bytearray, memoryview, BinaryIO]


class ApueClientBase:
    """Calls an apü API. `ops` is the API's operations (from the manifest), embedded by the generator."""

    OPS: dict = {}

    def __init__(self, base_url: str, *, cafile: Optional[str] = None, context: Optional[ssl.SSLContext] = None,
                 authorization: Optional[str] = None, retries: int = 2, backoff: float = 0.1, timeout: float = 60):
        parsed = urllib.parse.urlsplit(base_url)
        if parsed.scheme != "https":
            raise ValueError("apü servers speak HTTPS")
        self.base_url = base_url.rstrip("/")
        self._host, self._port = parsed.hostname, parsed.port or 443
        self._context = context or ssl.create_default_context(cafile=cafile)
        self._timeout = timeout
        self.authorization = authorization
        self.retries, self.backoff = retries, backoff
        self._conn: Optional[http.client.HTTPSConnection] = None

    def close(self) -> None:
        self._drop()

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

    def _drop(self) -> None:
        if self._conn is not None:
            self._conn.close()
            self._conn = None

    def _request(self, method: str, path: str, headers: dict, body) -> http.client.HTTPResponse:
        if self._conn is None:
            self._conn = http.client.HTTPSConnection(self._host, self._port, context=self._context, timeout=self._timeout)
        all_headers = {"accept-encoding": "identity", **headers}
        if self.authorization is not None:
            all_headers["authorization"] = self.authorization
        chunked = body is not None and not isinstance(body, (bytes, bytearray))
        self._conn.request(method, path, body=body, headers=all_headers, encode_chunked=chunked)
        return self._conn.getresponse()

    # -- uploads (bytes and file inputs) -------------------------------------------------------

    def upload(self, data: Uploadable) -> dict:
        """Uploads content to /$uploads in one request and returns its reference {"$upload": id}."""
        body = bytes(data) if isinstance(data, (bytes, bytearray, memoryview)) else iter(lambda: data.read(BLOB_CHUNK), b"")
        res = self._request("POST", "/$uploads", {"upload-complete": "?1", "content-type": "application/octet-stream"}, body)
        payload = res.read()
        if res.status != 201:
            raise _problem(res.status, payload)
        return {"$upload": json.loads(payload)["upload"]}

    def delete_upload(self, ref: dict) -> None:
        res = self._request("DELETE", f"/$uploads/{ref['$upload']}", {}, None)
        res.read()

    def _with_uploads(self, schema: dict, value: Any, created: list) -> Any:
        def replace(v: Any, _kind: str) -> Any:
            if isinstance(v, dict) and "$upload" in v:
                return v
            ref = self.upload(v)
            created.append(ref)
            return ref

        return _map(schema, value, ("blob-frames", "upload"), replace) if _transfers(schema, "blob-frames|upload") else value

    def _outputs(self, op: dict, value: Any) -> Any:
        schema = op["output"]
        if not _transfers(schema, "download"):
            return value
        return _map(schema, value, ("download",), lambda ref, _k: Download(ref, self))

    # -- calls ----------------------------------------------------------------------------------

    def _prepare(self, name: str, op: dict, value: Any, timeout_ms: Optional[int], key: Optional[str]) -> tuple[str, str, dict, Optional[bytes]]:
        headers = {"accept": ACCEPT}
        if timeout_ms is not None:
            headers["apue-timeout"] = str(int(timeout_ms))
        if op["effect"] == "safe" and op["stream"] in ("none", "server"):
            path = f"/{name}" if value is _ABSENT else f"/{name}?i={urllib.parse.quote(canonical_json(value), safe='')}"
            if len(path) <= MAX_GET_URL:
                return "GET", path, headers, None
        body = None if value is _ABSENT else json.dumps(value, separators=(",", ":")).encode()
        if body is not None:
            headers["content-type"] = "application/json"
        if op["effect"] != "safe" and op["stream"] == "none":
            headers["idempotency-key"] = '"' + (key or str(uuid.uuid4())) + '"'
        return "POST", f"/{name}", headers, body

    def _send(self, method: str, path: str, headers: dict, body, retry: bool) -> http.client.HTTPResponse:
        attempt = 0
        while True:
            try:
                res = self._request(method, path, headers, body)
                if retry and attempt < self.retries and (res.status in (429, 503)):
                    delay = res.getheader("retry-after")
                    res.read()
                    attempt += 1
                    time.sleep(float(delay) if delay and delay.isdigit() else random.random() * self.backoff * 2**attempt)
                    continue
                return res
            except (OSError, http.client.HTTPException):
                self._drop()
                if not retry or attempt >= self.retries:
                    raise
                attempt += 1
                time.sleep(random.random() * self.backoff * 2**attempt)

    def _frames(self, res: http.client.HTTPResponse) -> Iterator[tuple[int, int, bytes]]:
        while True:
            header = res.read(8)
            if not header:
                return
            if len(header) < 8:
                raise ApueError(502, {"title": "Truncated Stream", "detail": "incomplete frame header"})
            kind, flags, _lane, length = struct.unpack(">BBHI", header)
            payload = res.read(length) if length else b""
            if len(payload) < length:
                raise ApueError(502, {"title": "Truncated Stream", "detail": "incomplete frame"})
            yield kind, flags, payload

    def _decode(self, op: dict, res: http.client.HTTPResponse) -> Iterator[Any]:
        """The response's values: one for JSON, each MSG for framed responses."""
        ctype = (res.getheader("content-type") or "").split(";")[0].strip().lower()
        if res.status >= 400 or ctype != STREAM_JSON:
            body = res.read()
            if res.status >= 400 or ctype == "application/problem+json":
                raise _problem(res.status, body)
            yield self._outputs(op, json.loads(body))
            return
        blobs, chunks = [], []
        for kind, flags, payload in self._frames(res):
            if kind == BLOB:
                chunks.append(payload)
                if flags & FLAG_LAST:
                    blobs.append(b"".join(chunks))
                    chunks = []
            elif kind == MSG:
                used: set = set()
                value = _restore(json.loads(payload), blobs, used) if _transfers(op["output"], "blob-frames") else json.loads(payload)
                if len(used) != len(blobs):
                    raise ApueError(502, {"title": "Malformed Stream", "detail": "unreferenced blobs"})
                blobs = []
                yield self._outputs(op, value)
            elif kind == END:
                info = json.loads(payload)
                if info.get("status", 200) >= 400:
                    raise ApueError(info["status"], info.get("problem"))
                return
            # HEARTBEAT, CHECKPOINT and unknown frame types are ignored.
        raise ApueError(502, {"title": "Truncated Stream", "detail": "response ended without END frame"})

    def _call(self, name: str, value: Any = _ABSENT, *, timeout_ms: Optional[int] = None, idempotency_key: Optional[str] = None) -> Any:
        op = self.OPS[name]
        created: list = []
        try:
            value = self._with_uploads(op["input"], value, created) if value is not _ABSENT else value
            method, path, headers, body = self._prepare(name, op, value, timeout_ms, idempotency_key)
            retry = op["effect"] != "unsafe" or "idempotency-key" in headers
            res = self._send(method, path, headers, body, retry)
            values = list(self._decode(op, res))
            return values[0] if values else None
        finally:
            for ref in created:
                try:
                    self.delete_upload(ref)
                except (OSError, http.client.HTTPException):
                    pass

    def _stream(self, name: str, value: Any = _ABSENT, *, timeout_ms: Optional[int] = None) -> Iterator[Any]:
        op = self.OPS[name]
        method, path, headers, body = self._prepare(name, op, value, timeout_ms, None)
        res = self._send(method, path, headers, body, op["effect"] != "unsafe")
        try:
            yield from self._decode(op, res)
        finally:
            if not res.isclosed():
                self._drop()  # abandoned mid-stream: the connection can't be reused

    def _client_stream(self, name: str, inputs: Iterable[Any], *, timeout_ms: Optional[int] = None) -> Iterator[Any]:
        op = self.OPS[name]
        bytes_in = _transfers(op["input"], "blob-frames")

        def body() -> Iterator[bytes]:
            for item in inputs:
                if bytes_in:
                    yield b"".join(_message_frames(item))
                else:
                    yield _frame(MSG, json.dumps(item, separators=(",", ":")).encode())
            yield _frame(END, json.dumps({"status": 200}).encode())

        headers = {"accept": ACCEPT, "content-type": STREAM_JSON}
        if timeout_ms is not None:
            headers["apue-timeout"] = str(int(timeout_ms))
        res = self._request("POST", f"/{name}", headers, body())
        try:
            yield from self._decode(op, res)
        finally:
            if not res.isclosed():
                self._drop()
